import pyomo.environ as pyo

DATA = {
    "num_months": 6,
    "initial_inventory": 200,
    "capacity": 500,
    "purchase_price": [28, 24, 25, 27, 23, 23],
    "sale_price": [29, 24, 26, 28, 22, 25],
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set: months 7..12 represented as 1..6
    model.T = pyo.RangeSet(1, d["num_months"])

    def x_bounds(m, t):
        return (0, d["capacity"])

    def s_bounds(m, t):
        return (0, d["capacity"])

    def I_bounds(m, t):
        return (0, d["capacity"])

    # Variables
    model.x = pyo.Var(model.T, domain=pyo.NonNegativeReals, bounds=x_bounds)  # purchased
    model.s = pyo.Var(model.T, domain=pyo.NonNegativeReals, bounds=s_bounds)  # sold
    model.I = pyo.Var(model.T, domain=pyo.NonNegativeReals, bounds=I_bounds)  # ending inventory

    # Objective: maximize revenue = sales income minus purchase cost
    def obj_rule(m):
        return sum(
            d["sale_price"][t - 1] * m.s[t] - d["purchase_price"][t - 1] * m.x[t]
            for t in m.T
        )

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    # Inventory balance: I[t-1] + x[t] - s[t] = I[t]
    def balance_rule(m, t):
        prev = d["initial_inventory"] if t == 1 else m.I[t - 1]
        return prev + m.x[t] - m.s[t] == m.I[t]

    model.balance = pyo.Constraint(model.T, rule=balance_rule)

    # Capacity: ending inventory cannot exceed warehouse capacity (<=)
    def cap_rule(m, t):
        return m.I[t] <= d["capacity"]

    model.capacity = pyo.Constraint(model.T, rule=cap_rule)

    return model


